{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C47"],
      "claim": "Diflunisal, a halogenated salicylic acid with a carboxylic acid and phenol, had absolute bioavailability of 89.5% in a volunteer; its high assay-transfer score supports high oral bioavailability for the query's acidic aromatic carboxylic acid structure.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C26"],
      "claim": "Lumiracoxib, an arylacetic acid with chloro and amino substituents, showed absolute bioavailability of approximately 74% in healthy subjects and patients; this structurally relevant carboxylic acid/chloro/amine motif supports high F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C36"],
      "claim": "Safinamide absolute bioavailability was 95.3% in the fed state, demonstrating that a fed condition does not preclude high oral bioavailability; this directly supports the query's fed-state prediction.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C22"],
      "claim": "Telmisartan, a carboxylic acid-containing drug with solubility limitations, still had absolute bioavailability of 43% in humans; this supports F ≥ 20% for the query despite possible absorption challenges.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C13"],
      "claim": "Carbidopa/levodopa combination had mean absolute bioavailability of 71.0% in fed volunteers, providing additional fed-state evidence that oral bioavailability remains well above the 20% threshold.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "All high-transfer experimental analogues with relevant acidic, carboxylic acid, chloro, and aromatic features show absolute oral bioavailability well above 20% (43–95%), including fed-state data; the query is therefore predicted to have high oral bioavailability at the F ≥ 20% threshold.",
  "evidence_gaps": [
    "No direct experimental record for the query molecule itself is present in the supplied evidence.",
    "Fed-state-specific absolute bioavailability for the exact query is inferred from analogues rather than measured directly.",
    "Potential food effects on the query's absorption are not directly quantified, but available fed-state analogues remain far above the threshold."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

